package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.JdbcWorkspaceTasks;import ama.access.MeetingAccess;import ama.db.TransactionRunner;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class Task12WorkspaceTasksWireTest {
 static final String M="00000000-0000-4000-8000-000000000001",T="00000000-0000-4000-8000-000000000002";final ResolvedSession session=new ResolvedSession(new Actor("owner",Status.ACTIVE,Set.of(Role.USER)),"T".repeat(43),Instant.now().plusSeconds(60));
 @Test void strictTaskQueryRejectsUnknownAndRepeatedKeysBeforeReader()throws Exception{var reader=mock(JdbcWorkspaceTasks.class);var mvc=MockMvcBuilders.standaloneSetup(new WorkspaceTasksController(reader,mock(TransactionRunner.class),mock(MeetingAccess.class))).setControllerAdvice(new MeetingListErrors()).build();for(String q:List.of("limit=0","limit=51","limit=01","limit=1&limit=2","kind=OTHER","kind=ALL&kind=MINUTES_GENERATE_V1","owner=other","cursor=")){var response=mvc.perform(get("/api/v1/meetings/"+M+"/tasks?"+q).requestAttr(SessionSecurityFilter.SESSION,session)).andReturn().getResponse();assertEquals(400,response.getStatus(),q);assertEquals("private, no-store",response.getHeader("Cache-Control"));}verifyNoInteractions(reader);}
 @Test void taskCountersRemainTokensAndBoundedEmptyScanCanContinue()throws Exception{var reader=mock(JdbcWorkspaceTasks.class);when(reader.read(session.actor(),M,"ALL",20,null)).thenReturn(new JdbcWorkspaceTasks.Page(List.of(new JdbcWorkspaceTasks.Item(T,"TRANSCRIPT_IMPORT_V1","RUNNING","1","9007199254740993",T,"/api/v1/meetings/"+M+"/processing-tasks/"+T)),null,false,"PERSISTED_RELATION"));var mvc=MockMvcBuilders.standaloneSetup(new WorkspaceTasksController(reader,mock(TransactionRunner.class),mock(MeetingAccess.class))).setControllerAdvice(new MeetingListErrors()).build();var response=mvc.perform(get("/api/v1/meetings/"+M+"/tasks").requestAttr(SessionSecurityFilter.SESSION,session)).andReturn().getResponse();assertEquals(200,response.getStatus());assertTrue(response.getContentAsString().contains("\"businessRevisionToken\":\"9007199254740993\""));assertEquals("private, no-store",response.getHeader("Cache-Control"));when(reader.read(session.actor(),M,"ALL",20,null)).thenThrow(new ama.meeting.WorkspaceReadBudget.Unavailable(new IllegalStateException("private database detail")));var unavailable=mvc.perform(get("/api/v1/meetings/"+M+"/tasks").requestAttr(SessionSecurityFilter.SESSION,session)).andReturn().getResponse();assertEquals(503,unavailable.getStatus());assertFalse(unavailable.getContentAsString().contains("private database"));}

 @Test void missingInstallationStillChecksOwnerBeforeReturningUnavailable()throws Exception{var tx=mock(TransactionRunner.class);when(tx.required(any())).thenAnswer(call->((java.util.concurrent.Callable<?>)call.getArgument(0)).call());var access=mock(MeetingAccess.class);var gate=mock(MeetingAccess.Locked.class);when(access.lock(session.actor(),M)).thenReturn(gate);var mvc=MockMvcBuilders.standaloneSetup(new WorkspaceTasksController(null,tx,access)).setControllerAdvice(new MeetingListErrors()).build();var unavailable=mvc.perform(get("/api/v1/meetings/"+M+"/tasks").requestAttr(SessionSecurityFilter.SESSION,session)).andReturn().getResponse();assertEquals(503,unavailable.getStatus());verify(access).require(gate,MeetingAccess.Action.EDIT);doThrow(new MeetingAccess.AccessDeniedException()).when(access).require(gate,MeetingAccess.Action.EDIT);var denied=mvc.perform(get("/api/v1/meetings/"+M+"/tasks").requestAttr(SessionSecurityFilter.SESSION,session)).andReturn().getResponse();assertEquals(403,denied.getStatus());assertEquals("private, no-store",denied.getHeader("Cache-Control"));}
}
